#include <bits/stdc++.h>using namespace std;typedef long long ll;struct ListNode {    int val;    ListNode *next;    ListNode() : val(0), next(nullptr) {}    ListNode(int x) : val(x), next(nullptr) {}    ListNode(int x, ListNode *next) : val(x, next) {}};class Solution {public:    ListNode* reverseKGroup(ListNode* head, int k) {        if (!head || k == 1) return head;        ListNode* dummy = new ListNode(0);        dummy->next = head;        ListNode* p_t = dummy;        ListNode* curr = head;        while (curr) {            ListNode* tmp = curr;            int cnt = 0;            for(int i=0; i<k; ++i) {                if (!tmp) break;                tmp = tmp->next;                cnt++;            }            if (cnt < k) {                p_t->next = curr;                break;            }            ListNode* st = curr;            ListNode* prev = tmp;            ListNode* p = curr;            for (int i = 0; i < k; ++i) {                ListNode* nxt = p->next;                p->next = prev;                prev = p;                p = nxt;            }            p_t->next = prev;            p_t = st;            curr = p;        }        return dummy->next;    }};int main() {    ListNode* head = new ListNode(1);    head->next = new ListNode(2);    head->next->next = new ListNode(3);    head->next->next->next = new ListNode(4);    head->next->next->next->next = new ListNode(5);    Solution s;    ListNode* res = s.reverseKGroup(head, 2);    while(res) { cout << res->val << " "; res = res->next; }    return 0;}
